namespace {
void require(bool value, const QString &message) { if (!value) throw std::runtime_error(message.toStdString()); }
QString sha(const QString &path) {
    QFile file(path); if (!file.open(QIODevice::ReadOnly)) return {};
    QCryptographicHash hash(QCryptographicHash::Sha256);
    require(hash.addData(&file), QStringLiteral("Hash failed: ") + path);
    return QString::fromLatin1(hash.result().toHex());
}
void writeJson(const QString &path, const QJsonObject &object) {
    QSaveFile file(path); require(file.open(QIODevice::WriteOnly), file.errorString());
    const auto bytes=QJsonDocument(object).toJson(); require(file.write(bytes)==bytes.size() && file.commit(), file.errorString());
}
QJsonObject totalsJson(const OpRunner::Totals &t) {
    return {{"succeeded",t.succeeded},{"unchanged",t.unchanged},{"failed",t.failed},{"skipped",t.skipped},
            {"retained",t.retained},{"needsAttention",t.needsAttention},{"cancelled",t.cancelled}};
}
QJsonObject summaryJson(const OperationRecovery::Summary &s) {
    QJsonArray resumable,restorable;
    for(const auto &r:s.resumable) resumable.append(QJsonObject{{"journalPath",r.journalPath},{"remaining",r.remaining.size()},{"finished",r.finished},{"kind",opKindName(r.kind)}});
    for(const auto &r:s.restorable) restorable.append(QJsonObject{{"journalPath",r.journalPath},{"originals",QJsonArray::fromStringList(r.originals)},{"retainedPaths",QJsonArray::fromStringList(r.retainedPaths)}});
    QJsonObject result{{"resumable",resumable},{"restorable",restorable},{"opsFlagged",s.opsFlagged},{"notes",QJsonArray::fromStringList(s.notes)}};
    if(s.undoCandidate) result.insert("undoCandidate",s.undoCandidate->path);
    return result;
}
QJsonArray recordsJson(const QString &directory) {
    QJsonArray out;
    for(const auto &r:OpJournal::scan(directory)) {
        QJsonArray entries;
        for(const auto &e:r.entries) {
            auto object=e.json();
            object.insert("srcExists",QFile::exists(e.item.src)); object.insert("srcSha256",sha(e.item.src));
            object.insert("dstExists",QFile::exists(e.dst)); object.insert("dstSha256",sha(e.dst));
            object.insert("retirementExists",QFile::exists(e.retirement)); object.insert("retirementSha256",sha(e.retirement));
            object.insert("complete",e.complete()); object.insert("needsOriginalRestoration",e.needsOriginalRestoration()); entries.append(object);
        }
        out.append(QJsonObject{{"path",r.path},{"kind",opKindName(r.request.kind)},{"stopped",r.stopped},{"dismissed",r.dismissed},{"undoPath",r.undoPath},{"undoOf",r.request.undoOf},{"entries",entries},{"corrupt",r.corrupt},{"torn",r.torn}});
    }
    return out;
}
struct Sink final:OpSink {
    QStringList messages; QJsonArray outcomes;
    void progress(const QString &,int,int,double) override {}
    void log(QtMsgType,const QString &message) override {messages.append(message);}
    void trashUsed(const QString &folder,int count) override {messages.append(QStringLiteral("MediaMuster Trash %1: %2").arg(count).arg(folder));}
    void result(const OpResult &r) override {outcomes.append(QJsonObject{{"state",int(r.state)},{"source",r.source},{"destination",r.destination},{"message",r.message},{"sourceRemoved",r.sourceRemoved},{"restoredOriginalPath",r.restoredOriginalPath}});}
    bool confirmTrashFallback(const QVector<OpTrashFallbackItem> &) override {return false;}
};
QJsonArray rowsJson(const QVector<MediaFile> &rows) {
    QJsonArray out;
    for(const auto &r:rows) out.append(QJsonObject{{"path",r.mediaFilePath},{"bytes",r.sizeBytes},{"sha256",sha(r.mediaFilePath)},{"fileMobId",r.fileMobId},{"masterMobId",r.masterMobId},{"compactReceipt",bool(r.operationScanReceipt)},{"headerFileMobId",r.operationScanReceipt?r.operationScanReceipt->headerIdentity.fileMobId:QString{}}});
    return out;
}
}
int main(int argc,char **argv) {
    QCoreApplication app(argc,argv);
    app.setOrganizationName(QStringLiteral("CoplandDisposableVerification"));
    app.setApplicationName(QStringLiteral("CoreFileOperations20261018"));
    const auto args=app.arguments();
    if(args.size()<5) return 2;
    const QString action=args[1], root=OpJournal::canonicalPath(args[2]), kind=args[3], output=args[4];
    const QString crash=args.size()>5?args[5]:QString{};
    QJsonObject report{{"action",action},{"root",root},{"kind",kind},{"crashCheckpoint",crash},{"pid",qint64(QCoreApplication::applicationPid())},{"qtVersion",qVersion()}};
    try {
        require(root.startsWith(QStringLiteral("/private/tmp/copland-file-operations-20261018/core/scenarios/")),QStringLiteral("Unsafe scenario location"));
        const QString journals=root+QStringLiteral("/journals");
        require(qputenv("MEDIAMUSTER_JOURNAL_DIR",journals.toUtf8()),QStringLiteral("Cannot isolate journal env"));
        Sink sink; std::atomic<bool> cancel{false}; OpRunner runner(sink,cancel);
        runner.hooks.forceCopy=kind==QStringLiteral("move-copy");
        runner.hooks.forceNetworkTrash=kind!=QStringLiteral("delete-native");
        OpRequest request; request.diagnosticTrashRoot=root+QStringLiteral("/MediaMuster Trash");
        if(kind==QStringLiteral("delete-native")) request.diagnosticTrashRoot.clear();
        if(action==QStringLiteral("operate")) {
            QVector<MediaFile> rows; QWeakPointer<const SourceSnapshot> sourceOwner;
            {
                MediaEngine::Cancellation cancellation;
                const QString mxf=root+QStringLiteral("/source/Avid MediaFiles/MXF");
                const auto scan=MediaEngine::ScanEngine{}.scan({{mxf},false},cancellation);
                require(scan.reconciliationComplete && !scan.cancelled,QStringLiteral("Incomplete initial scan"));
                require(scan.files.size()==(kind==QStringLiteral("rebalance")?2:1),QStringLiteral("Unexpected scan row count: %1").arg(scan.files.size()));
                require(!scan.sources.isEmpty(),QStringLiteral("No scan source receipts"));
                sourceOwner=scan.sources.front().snapshot;
                const ScanRowLookup lookup(scan);
                for(const auto &file:scan.files) rows.append(mediaEngineMediaFile(file,lookup,root,QStringLiteral("Disposable test")));
            }
            require(sourceOwner.isNull(),QStringLiteral("Scan still retained"));
            report.insert("scanSourcesReleased",sourceOwner.isNull()); report.insert("rows",rowsJson(rows));
            for(const auto &row:rows) {
                require(row.operationScanReceipt.has_value(),QStringLiteral("Missing compact scan receipt"));
                require(!row.fileMobId.isEmpty() && !row.operationScanReceipt->headerIdentity.fileMobId.isEmpty(),QStringLiteral("Missing scanned identity"));
            }
            if(kind==QStringLiteral("rebalance")) {
                const auto plan=RebalancePlanner::computePlan(root+QStringLiteral("/source/Avid MediaFiles/MXF"),QStringLiteral("Disposable"),rows);
                report.insert("rebalancePlannedMoves",plan.moveCount());
                require(plan.moveCount()==1,QStringLiteral("Unexpected Rebalance plan"));
                request=RebalancePlanner::requestForPlan(plan);
                request.diagnosticTrashRoot=root+QStringLiteral("/MediaMuster Trash");
            } else {
                request.kind=kind==QStringLiteral("copy")?OpKind::Copy:kind.startsWith(QStringLiteral("move"))?OpKind::Move:OpKind::Delete;
                request.items=OpManager::itemsFromMediaFiles(rows,{});
                request.destRoot=root+QStringLiteral("/destination"); request.preserve=true;
            }
            rows.clear();
            if(!crash.isEmpty()) runner.hooks.checkpoint=[&](const QString &point,const OpJournal::Entry &entry) {
                if(point!=crash) return;
                auto stopped=report; stopped.insert("checkpointObserved",point); stopped.insert("entryAtExit",entry.json()); stopped.insert("sentinelSha256",sha(root+QStringLiteral("/unrelated.keep")));
                writeJson(root+QStringLiteral("/crash-observed.json"),stopped);
                std::_Exit(81);
            };
        } else {
            report.insert("beforeRecovery",summaryJson(OperationRecovery::readSummary(journals)));
            const auto recovered=OperationRecovery::run(journals);
            report.insert("startupRecovery",summaryJson(recovered));
            if(action==QStringLiteral("resume")) {
                if(recovered.resumable.isEmpty()) {
                    const auto saved=OpJournal::scan(journals);
                    require(!saved.isEmpty(),QStringLiteral("Missing recovery journal"));
                    for(const auto &record:saved) for(const auto &entry:record.entries) require(entry.complete(),QStringLiteral("Unfinished job not offered for resume"));
                    report.insert("reconciledComplete",true);
                } else {
                    require(recovered.resumable.size()==1,QStringLiteral("Unexpected resumable job count"));
                    request.resumeJournalPath=recovered.resumable.front().journalPath;
                }
            } else if(action==QStringLiteral("restore")) {
                require(recovered.restorable.size()==1,QStringLiteral("Expected retained original to restore"));
                request.restoreJournalPath=recovered.restorable.front().journalPath;
            } else if(action==QStringLiteral("undo")) {
                require(recovered.undoCandidate.has_value(),QStringLiteral("Undo unavailable after process restart"));
                request.kind=OpKind::Undo; request.undoEnabled=true;
                request.undoJournalPath=recovered.undoCandidate->path;
            } else require(false,QStringLiteral("Unknown action"));
        }
        if(!report.value("reconciledComplete").toBool()) {
            const auto totals=runner.run(request,journals); report.insert("totals",totalsJson(totals));
            require(crash.isEmpty(),QStringLiteral("Crash checkpoint was not reached"));
            require(totals.succeeded==1 && totals.failed==0 && totals.needsAttention==0,QStringLiteral("Operation failed: ")+sink.messages.join('\n'));
        }
        report.insert("messages",QJsonArray::fromStringList(sink.messages));report.insert("outcomes",sink.outcomes);
        report.insert("after",summaryJson(OperationRecovery::readSummary(journals)));report.insert("records",recordsJson(journals));
        report.insert("sentinelSha256",sha(root+QStringLiteral("/unrelated.keep"))); report.insert("ok",true);
        writeJson(output,report); return 0;
    } catch(const std::exception &error) {
        report.insert("error",QString::fromUtf8(error.what()));report.insert("ok",false);
        report.insert("records",recordsJson(root+QStringLiteral("/journals")));
        writeJson(output,report); QTextStream(stderr)<<error.what()<<'\n';return 1;
    }
}

