QByteArray bytes(const QString &path)
{
    QFile file(path);
    return file.open(QIODevice::ReadOnly) ? file.readAll() : QByteArray{};
}
QString hash(const QString &path)
{
    const auto contents = bytes(path);
    return contents.isEmpty() ? QString{} : QString::fromLatin1(QCryptographicHash::hash(contents, QCryptographicHash::Sha256).toHex());
}
bool waitUntil(const std::function<bool()> &ready, int timeoutMs = 30000)
{
    if (ready()) return true;
    QEventLoop loop;
    QTimer poll, timeout;
    poll.setInterval(10);
    timeout.setSingleShot(true);
    QObject::connect(&poll, &QTimer::timeout, &loop, [&] { if (ready()) loop.quit(); });
    QObject::connect(&timeout, &QTimer::timeout, &loop, &QEventLoop::quit);
    poll.start(); timeout.start(timeoutMs); loop.exec();
    return ready();
}
void saveJson(const QString &path, const QJsonObject &object)
{
    QFile output(path);
    if (!output.open(QIODevice::WriteOnly | QIODevice::Truncate))
        throw std::runtime_error("Cannot save probe evidence");
    output.write(QJsonDocument(object).toJson());
}
}

// This scratch class uses the existing UI-test friendship, without replacing any
// production scan, dialog, controller, file operation or model behavior.
class TestOperationUi
{
public:
static int run(const QString &phase, const QString &kind, const QString &root, const QString &seed)
{
    QJsonObject checks;
    QJsonObject report{{"phase", phase}, {"kind", kind}, {"root", root},
        {"platform", QGuiApplication::platformName()}, {"pid", double(QCoreApplication::applicationPid())},
        {"scope", "Native Qt dialog/controller/model acceptance with disposable complete MXF media"}};
    const auto require = [&](bool condition, const QString &name) {
        checks.insert(name, condition);
        if (!condition) throw std::runtime_error(name.toStdString());
    };
    const QString sourceBase = root + "/source";
    const QString destinationBase = root + "/destination";
    const auto savedManifest = QJsonDocument::fromJson(bytes(root + "/manifest.json")).object();
    const QString source = phase == "recovery" ? savedManifest["source"].toString() : sourceBase + "/Avid MediaFiles/MXF/1/disposable-tone.mxf";
    const QString destination = destinationBase + "/Avid MediaFiles/MXF/1/" + QFileInfo(source).fileName();
    const QString output = root + "/ui-" + phase + ".json";
    const QString manifestPath = root + "/manifest.json";
    int result = 0;
    try
    {
        require(root.startsWith("/private/tmp/copland-file-operations-20261018/"), "scratchOnlyRoot");
        require(QGuiApplication::platformName() == "cocoa", "nativeCocoaPlatform");
        require(!QFile::exists(output), "freshEvidenceOutput");
        QString expectedHash;
        if (phase == "run")
        {
            require(!QFile::exists(manifestPath) && !QFile::exists(source), "freshScenario");
            require(QDir().mkpath(QFileInfo(source).absolutePath()) && QDir().mkpath(destinationBase), "scenarioDirectoriesCreated");
            expectedHash = hash(seed);
            require(!expectedHash.isEmpty() && QFile::copy(seed, source), "genuineMediaCopied");
            require(hash(source) == expectedHash, "disposableCopyHashMatchesSeed");
            saveJson(manifestPath, {{"source", source}, {"destination", destination}, {"seed", seed}, {"sha256", expectedHash}});
        }
        else
            expectedHash = savedManifest["sha256"].toString(savedManifest["seedSha256"].toString());
        require(!expectedHash.isEmpty(), "expectedHashAvailable");
        report.insert("source", source); report.insert("destination", destination); report.insert("sha256", expectedHash);
        qputenv("MEDIAMUSTER_JOURNAL_DIR", (root + "/journals").toUtf8());
        Diagnostics::install(root + "/diagnostics-" + phase);
        report.insert("log", Diagnostics::logPath());

        MainWindow window(nullptr, MainWindow::StartupMode::UiOnly);
        window.show(); window.raise(); window.activateWindow(); QApplication::processEvents();
        auto *operations = window.m_operations;
        int finished = 0, succeeded = -1, failed = -1, scans = 0;
        QObject::connect(operations->manager(), &OpManager::operationFinished, &window,
            [&](int good, int bad) { ++finished; succeeded = good; failed = bad; });
        QObject::connect(window.m_scanner, &MediaScanner::scanFinished, &window,
            [&](const QVector<MediaFile> &) { ++scans; });
        const auto settled = [&] { return operations->isIdle() && !operations->m_historyLoading; };
        const auto scan = [&](const QStringList &locations, int expectedRows) {
            const int before = scans;
            window.rescanPaths(locations);
            require(waitUntil([&] { return scans > before && settled(); }), "currentScannerCompleted");
            require(window.m_model->rowCount() == expectedRows, "scannedInventoryCount");
            for (const auto &file : window.m_model->allFiles())
                require(file.operationScanReceipt.has_value() && !file.fileMobId.isEmpty(), "preparedRowsHaveCompactSafetyReceipt");
        };
        bool recoveryDialogSeen = false, recoveryResumeClicked = false;
        QTimer recover;
        if (phase == "recovery")
        {
            scan({sourceBase}, 1);
            recover.setInterval(20);
            QObject::connect(&recover, &QTimer::timeout, &window, [&] {
                auto *dialog = qobject_cast<QDialog *>(QApplication::activeModalWidget());
                if (!dialog || dialog->objectName() != "unfinishedBusinessDialog") return;
                recoveryDialogSeen = true;
                auto *resume = dialog->findChild<QPushButton *>("resumeInterruptedJobButton");
                if (resume && resume->isEnabled())
                {
                    dialog->grab().save(root + "/ui-startup-recovery.png");
                    recoveryResumeClicked = true; recover.stop(); resume->click();
                }
            });
            recover.start();
        }
        operations->runStartupRecovery();
        require(waitUntil([&] { return phase == "recovery" ? recoveryResumeClicked && finished == 1 && settled() : settled(); }), "startupHistoryLoaded");
        recover.stop();

        if (phase == "run")
        {
            scan({sourceBase}, 1);
            window.m_tableView->selectRow(0);
            QApplication::processEvents();
            require(window.selectedFiles().size() == 1 && window.m_manageMediaAction->isEnabled(), "scannedRowSelectedForManageMedia");
            bool configured = false, executed = false, dialogSeen = false;
            QTimer operate, deadline;
            deadline.setSingleShot(true);
            QObject::connect(&deadline, &QTimer::timeout, &window, [&] {
                if (auto *dialog = qobject_cast<QDialog *>(QApplication::activeModalWidget())) dialog->reject();
            });
            operate.setInterval(20);
            QObject::connect(&operate, &QTimer::timeout, &window, [&] {
                auto *dialog = qobject_cast<ManageMediaDialog *>(QApplication::activeModalWidget());
                if (!dialog) return;
                dialogSeen = true;
                if (!configured)
                {
                    configured = true;
                    if (kind == "move") dialog->m_radioMove->click();
                    else if (kind == "delete") dialog->m_radioDelete->click();
                    else dialog->m_radioCopy->click();
                    if (kind != "delete")
                    {
                        dialog->m_chkPreserve->setChecked(true);
                        dialog->m_destPath->setText(destinationBase);
                    }
                    return;
                }
                if (!executed && !dialog->m_checkingDest && dialog->m_executeButton->isEnabled())
                {
                    dialog->grab().save(root + "/manage-dialog.png");
                    executed = true;
                    dialog->m_executeButton->click();
                }
            });
            operate.start(); deadline.start(30000);
            window.m_manageMediaAction->trigger();
            operate.stop(); deadline.stop();
            require(dialogSeen && configured && executed, "actualManageMediaDialogConfiguredAndAccepted");
            require(waitUntil([&] { return finished == 1 && settled(); }), "realControllerOperationCompleted");
            require(succeeded == 1 && failed == 0, "oneFileSucceededWithoutFailure");
            const auto records = OpJournal::scan(root + "/journals");
            require(records.size() == 1 && !records.first().entries.isEmpty(), "durableForwardJournalWritten");
            const auto &record = records.first();
            report.insert("forwardJournal", record.path);
            report.insert("landedPath", record.entries.first().dst);
            report.insert("trashProvider", record.entries.first().trashProvider);
            require(record.entries.first().complete(), "forwardEntryComplete");
            require(hash(record.entries.first().dst) == expectedHash, "landedFileHashUnchanged");
            require(QFile::exists(source) == (kind == "copy"), "sourcePresenceMatchesOperation");
            require(window.m_model->rowCount() == (kind == "copy" ? 2 : kind == "move" ? 1 : 0), "modelReflectsConfirmedOperation");
            require(operations->undoAction()->isEnabled(), "latestUndoOffered");
            report.insert("consoleContainsPhysicalFilename", window.m_console->toPlainText().contains("disposable-tone.mxf"));
            report.insert("consoleNote", "A successful Copy/Move may supply no message and therefore no per-file Console line; observed without changing product behavior.");
            if (kind == "delete") require(record.entries.first().trashProvider == "system", "nativeMacTrashUsed");
        }
        else if (phase == "undo" || phase == "recovery")
        {
            if (phase == "recovery")
            {
                require(recoveryDialogSeen && recoveryResumeClicked, "actualStartupRecoveryDialogResumed");
                require(finished == 1 && succeeded == 1 && failed == 0, "startupResumeCompletedRealCopy");
                require(hash(source) == expectedHash && hash(destination) == expectedHash, "startupResumePreservesOriginalAndCopyBytes");
                require(window.m_model->rowCount() == 2, "startupResumeAddsDestinationToModel");
            }
            const auto history = OperationRecovery::readSummary(root + "/journals");
            require(history.undoCandidate.has_value() && history.resumable.isEmpty(), "freshProcessFindsLatestCompletedJob");
            report.insert("forwardJournal", history.undoCandidate->path);
            const QString landed = history.undoCandidate->entries.first().dst;
            report.insert("landedPath", landed);
            if (phase == "undo" && kind == "copy") scan({sourceBase, destinationBase}, 2);
            else if (phase == "undo" && kind == "move") scan({destinationBase}, 1);
            require(operations->undoAction()->isEnabled(), "freshProcessUndoMenuEnabled");
            const int finishedBeforeUndo = finished;
            bool confirmed = false;
            QTimer confirm;
            confirm.setInterval(20);
            QObject::connect(&confirm, &QTimer::timeout, &window, [&] {
                if (auto *box = qobject_cast<QMessageBox *>(QApplication::activeModalWidget()))
                    for (auto *button : box->buttons())
                        if (box->buttonRole(button) == QMessageBox::AcceptRole)
                        {
                            confirmed = true; confirm.stop();
                            box->grab().save(root + "/undo-confirmation.png");
                            button->click(); return;
                        }
            });
            confirm.start(); operations->undoAction()->trigger(); confirm.stop();
            require(confirmed, "actualUndoMenuConfirmationAccepted");
            require(waitUntil([&] { return finished == finishedBeforeUndo + 1 && settled() && QFile::exists(source); }), "freshProcessUndoCompleted");
            require(waitUntil([&] { return settled() && window.m_model->rowCount() == 1; }), "modelRestoredOriginalRow");
            require(succeeded == 1 && failed == 0 && hash(source) == expectedHash, "undoRestoresExactOriginalBytes");
            require(!QFile::exists(landed), "forwardResultRemovedByUndo");
            const auto finalHistory = OperationRecovery::readSummary(root + "/journals");
            require(finalHistory.resumable.isEmpty() && !finalHistory.undoCandidate, "completedUndoLeavesNoPendingOrOlderUndo");
            require(window.m_model->allFiles().front().mediaFilePath == source, "tableShowsRestoredPhysicalPath");
            require(window.m_console->toPlainText().contains("Undoing the previous operation."), "consoleConfirmsUndoRequest");
            // Copy Undo deliberately uses system Trash. Collect only the exact
            // disposable item identified by our own inverse journal receipt.
            if (kind == "copy")
                for (const auto &record : OpJournal::scan(root + "/journals"))
                    if (record.request.kind == OpKind::Undo)
                        for (const auto &entry : record.entries)
                            if (entry.trashProvider == "system" && !entry.trashReceipt.isEmpty())
                            {
                                const QString collected = root + "/collected-trash-copy/" + QFileInfo(source).fileName();
                                require(QDir().mkpath(QFileInfo(collected).absolutePath()) && !QFile::exists(collected), "freshOwnTrashCollectionPath");
                                std::atomic<bool> cancel{false};
                                const auto restored = OpTrash::restore(entry.trashReceipt, collected, entry.landed, cancel, entry.dst);
                                report.insert("collectedOwnTrashPath", collected);
                                report.insert("originalOwnTrashPath", entry.dst);
                                report.insert("ownTrashCollectionError", restored.error);
                                require(restored.outcome == OpTrash::Outcome::Succeeded && hash(collected) == expectedHash && !QFile::exists(entry.dst), "ownDisposableTrashCopyCollectedByExactReceipt");
                            }
        }
        else require(false, "knownPhase");
        require(window.grab().save(root + "/window-" + phase + ".png"), "nativeWindowScreenshotSaved");
        report.insert("consoleText", window.m_console->toPlainText());
        report.insert("finalRows", window.m_model->rowCount());
        report.insert("scans", scans);
        report.insert("operationFinishes", finished);
        report.insert("succeeded", succeeded); report.insert("failed", failed);
        QThreadPool::globalInstance()->waitForDone();
    }
    catch (const std::exception &error)
    {
        report.insert("error", QString::fromUtf8(error.what()));
        result = 1;
    }
    report.insert("checks", checks); report.insert("exitCode", result);
    saveJson(output, report);
    return result;
}
};

int main(int argc, char **argv)
{
    QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);
    QApplication app(argc, argv);
    app.setOrganizationName("CoplandVerification");
    app.setApplicationName("CoplandDisposableOperations20261018");
    app.setApplicationVersion("0.0.2");
    app.setQuitOnLastWindowClosed(false);
    if (argc != 5) return 2;
    return TestOperationUi::run(QString::fromLocal8Bit(argv[1]), QString::fromLocal8Bit(argv[2]),
        QString::fromLocal8Bit(argv[3]), QString::fromLocal8Bit(argv[4]));
}
